using System;
using System.Globalization;
using System.IO;
using AjaxControlToolkit;
using DCore;
using InformationWeb;

namespace InformationWeb.Controls.Employee_V2
{
    /// <summary>
    /// Upload / xem tập tin tab chi tiết nhân sự V2 (công tác: Data/HRS_Task/{EmployeeID}/...).
    /// </summary>
    public static class EmployeeV2DetailFileUpload
    {
        private const string PhysicalSubFolder = "Data\\HRS_Task\\";
        private const string LogicalSubFolder = "Data/HRS_Task/";

        public static string GetPhysicalRoot()
        {
            string root = Globals.GetConfig("PhysicalDirectory_Upload");
            if (string.IsNullOrWhiteSpace(root))
                return string.Empty;
            if (!root.EndsWith("\\"))
                root += "\\";
            return root + PhysicalSubFolder;
        }

        public static string GetLogicalRoot()
        {
            string root = Globals.GetConfig("LogicalDirectory_Upload");
            if (string.IsNullOrWhiteSpace(root))
                return string.Empty;
            if (!root.EndsWith("/"))
                root += "/";
            return root + LogicalSubFolder;
        }

        public static bool HasAttachment(string relativePath)
        {
            return !string.IsNullOrWhiteSpace(relativePath);
        }

        public static string GetDisplayFileName(string relativePath)
        {
            if (string.IsNullOrWhiteSpace(relativePath))
                return string.Empty;
            return Path.GetFileName(relativePath.Replace('/', Path.DirectorySeparatorChar));
        }

        public static string GetPhysicalPathFromRelative(string relativePath)
        {
            if (string.IsNullOrWhiteSpace(relativePath))
                return string.Empty;

            string normalized = relativePath.Trim().Replace('\\', '/');
            if (normalized.IndexOf("..", StringComparison.Ordinal) >= 0)
                return string.Empty;

            string[] parts = normalized.Split('/');
            if (parts.Length != 2)
                return string.Empty;

            return Path.Combine(GetPhysicalRoot(), parts[0], parts[1]);
        }

        public static bool IsBlockedExtension(string fileName)
        {
            if (string.IsNullOrWhiteSpace(fileName))
                return true;

            string ext = Path.GetExtension(fileName);
            if (string.IsNullOrEmpty(ext) || ext.Length < 2)
                return true;

            ext = ext.TrimStart('.').ToLower(CultureInfo.InvariantCulture);
            return ext == "exe" || ext == "dll" || ext == "bat" || ext == "cgi" || ext == "com"
                || ext == "msi" || ext == "ashx" || ext == "asmx" || ext == "aspx";
        }

        public static string SanitizeOriginalFileName(string fileName)
        {
            string name = Path.GetFileName(fileName ?? string.Empty).Replace(" ", "-");
            foreach (char c in Path.GetInvalidFileNameChars())
                name = name.Replace(c, '-');
            if (string.IsNullOrWhiteSpace(name))
                return "file.dat";
            return name;
        }

        public static string BuildStoredFileName(long taskId, long employeeId, string originalFileName)
        {
            string safe = SanitizeOriginalFileName(originalFileName);
            string stamp = DateTime.Now.ToString("yyyyMMddHHmmss", CultureInfo.InvariantCulture);
            if (taskId > 0)
                return string.Format(CultureInfo.InvariantCulture, "{0}_{1}_{2}", taskId, stamp, safe);
            return string.Format(CultureInfo.InvariantCulture, "0_{0}_{1}_{2}", employeeId, stamp, safe);
        }

        public static string BuildRelativeLink(long employeeId, string storedFileName)
        {
            return string.Format(CultureInfo.InvariantCulture, "{0}/{1}", employeeId, storedFileName);
        }

        public static string SaveUpload(AsyncFileUpload upload, long employeeId, long taskId)
        {
            if (upload == null || !upload.HasFile || employeeId <= 0)
                return null;
            if (IsBlockedExtension(upload.FileName))
                return null;

            string storedName = BuildStoredFileName(taskId, employeeId, upload.FileName);
            string folder = Path.Combine(GetPhysicalRoot(), employeeId.ToString(CultureInfo.InvariantCulture));
            Directory.CreateDirectory(folder);
            string fullPath = Path.Combine(folder, storedName);
            upload.SaveAs(fullPath);
            return BuildRelativeLink(employeeId, storedName);
        }

        public static string FinalizeLinkAfterAdd(long employeeId, long taskId, string currentLink)
        {
            if (taskId <= 0 || employeeId <= 0 || string.IsNullOrWhiteSpace(currentLink))
                return currentLink;

            string physical = GetPhysicalPathFromRelative(currentLink);
            if (string.IsNullOrEmpty(physical) || !File.Exists(physical))
                return currentLink;

            string fileName = Path.GetFileName(physical);
            string prefix = string.Format(CultureInfo.InvariantCulture, "0_{0}_", employeeId);
            if (!fileName.StartsWith(prefix, StringComparison.Ordinal))
                return currentLink;

            string remainder = fileName.Substring(prefix.Length);
            int underscore = remainder.IndexOf('_');
            if (underscore < 0)
                return currentLink;

            string rest = remainder.Substring(underscore + 1);
            string newFileName = string.Format(CultureInfo.InvariantCulture, "{0}_{1}", taskId, rest);
            string newPhysical = Path.Combine(Path.GetDirectoryName(physical), newFileName);
            if (File.Exists(newPhysical))
                File.Delete(newPhysical);
            File.Move(physical, newPhysical);
            return BuildRelativeLink(employeeId, newFileName);
        }

        public static void DeletePhysicalFileIfExists(string relativePath)
        {
            if (string.IsNullOrWhiteSpace(relativePath))
                return;

            long employeeId = 0;
            string norm = relativePath.Trim().Replace('\\', '/');
            int slash = norm.IndexOf('/');
            if (slash > 0)
                long.TryParse(norm.Substring(0, slash), NumberStyles.Integer, CultureInfo.InvariantCulture, out employeeId);

            TaskAttachmentFileLifecycle.DiscardPending(GetPhysicalRoot(), employeeId, relativePath);
        }

        public static bool TryBuildViewUrl(string relativePath, string userName, out string url, out string errorMessage)
        {
            url = string.Empty;
            errorMessage = string.Empty;

            if (string.IsNullOrWhiteSpace(relativePath))
            {
                errorMessage = "Không có tập tin để xem.";
                return false;
            }

            if (string.IsNullOrWhiteSpace(userName))
            {
                errorMessage = "Phiên làm việc đã hết. Vui lòng đăng nhập lại.";
                return false;
            }

            string physicalPath = GetPhysicalPathFromRelative(relativePath);
            if (!File.Exists(physicalPath))
            {
                errorMessage = "Tập tin không còn trên máy chủ.";
                return false;
            }

            string displayName = GetDisplayFileName(relativePath);
            string fileType = Path.GetExtension(physicalPath).TrimStart('.').ToLower(CultureInfo.InvariantCulture);
            if (fileType == "pdf" || fileType == "doc" || fileType == "docx" || fileType == "xls" || fileType == "xlsx")
            {
                url = Globals.ApplicationVRoot + string.Format(CultureInfo.InvariantCulture,
                    "/viewer.html?filetype={0}&key={1}",
                    fileType,
                    ViewFile.GenerateKeyForExport(physicalPath, displayName, userName, "Viet$cong"));
            }
            else
            {
                url = Globals.ApplicationVRoot + "/DownloadFile.ashx?key="
                    + DownloadFile.GenerateKeyForExport(physicalPath, displayName, userName, "Viet$minh");
            }

            return true;
        }
    }
}

