        protected void fileUploadAttachment_UploadedComplete(object sender, AsyncFileUploadEventArgs e)
        {
            Session[GetUploadSessionKey()] = null;

            if (fileUploadAttachment == null || !fileUploadAttachment.HasFile)
                return;

            if (EmployeeV2DetailFileUpload.IsBlockedExtension(fileUploadAttachment.FileName))
            {
                Session[GetUploadSessionKey()] = "ERR:Loại tập tin không được phép.";
                return;
            }

            long employeeId = GetEmployeeId();
            if (employeeId <= 0)
                return;

            long taskId = 0;
            long.TryParse(hdnTaskID.Value, out taskId);

            string relativePath = EmployeeV2DetailFileUpload.SaveUpload(fileUploadAttachment, employeeId, taskId);
            if (!string.IsNullOrWhiteSpace(relativePath))
                Session[GetUploadSessionKey()] = relativePath;
        }

        protected void lbtPostAttachment_Click(object sender, EventArgs e)
        {
            object uploadedPath = Session[GetUploadSessionKey()];
            if (uploadedPath != null)
            {
                string raw = uploadedPath.ToString();
                if (raw.StartsWith("ERR:", StringComparison.Ordinal))
                {
                    MsgBox.ShowWarning(raw.Substring(4));
                }
                else
                {
                    string oldPath = GetLinkRelativePath();
                    if (!string.IsNullOrEmpty(oldPath)
                        && !string.Equals(oldPath, raw, StringComparison.OrdinalIgnoreCase))
                    {
                        EmployeeV2DetailFileUpload.DeletePhysicalFileIfExists(oldPath);
                    }

                    SetLinkRelativePath(raw);
                    if (udpAttachment != null)
                        udpAttachment.Update();
                }
            }

            Session[GetUploadSessionKey()] = null;
            ScheduleOpenModalAfterUpdate();
            udpAll.Update();
        }

        protected void lnkViewAttachment_Click(object sender, EventArgs e)
        {
            OpenAttachmentView(GetLinkRelativePath());
            ScheduleOpenModalAfterUpdate();
            udpAll.Update();
        }

        protected void lbtlDeleteAttachment_Click(object sender, EventArgs e)
        {
            string relativePath = GetLinkRelativePath();
            if (!string.IsNullOrWhiteSpace(relativePath))
                EmployeeV2DetailFileUpload.DeletePhysicalFileIfExists(relativePath);

            SetLinkRelativePath(string.Empty);
            RefreshAttachmentUi();
            if (udpAttachment != null)
                udpAttachment.Update();
            ScheduleOpenModalAfterUpdate();
            udpAll.Update();
        }

        private string GetUploadSessionKey()
        {
            return "EmpV2_CongTacEdit_fileUpload_" + ClientID;
        }

        private string GetLinkRelativePath()
        {
            if (hidLinkRelative == null)
                return string.Empty;
            return hidLinkRelative.Value ?? string.Empty;
        }

        private void SetLinkRelativePath(string relativePath)
        {
            string value = relativePath ?? string.Empty;
            if (hidLinkRelative != null)
                hidLinkRelative.Value = value;
            if (txtAttachmentDisplay != null)
            {
                txtAttachmentDisplay.Text = EmployeeV2DetailFileUpload.HasAttachment(value)
                    ? EmployeeV2DetailFileUpload.GetDisplayFileName(value)
                    : string.Empty;
            }
        }

        private static string NormalizeLinkForSave(string link)
        {
            if (string.IsNullOrWhiteSpace(link))
                return null;
            return link.Trim();
        }

        private void RefreshAttachmentUi()
        {
            bool hasFile = EmployeeV2DetailFileUpload.HasAttachment(GetLinkRelativePath());
            bool canEdit = EmployeeV2TabCanEdit.CanEdit(Session);

            if (lnkViewAttachment != null)
                lnkViewAttachment.Visible = hasFile;
            if (lbtlDeleteAttachment != null)
                lbtlDeleteAttachment.Visible = hasFile && canEdit;
            if (fileUploadAttachment != null)
                fileUploadAttachment.Visible = canEdit;
        }

        private void OpenAttachmentView(string relativePath)
        {
            string userName = User != null ? User.UserName : string.Empty;
            string url;
            string errorMessage;
            if (!EmployeeV2DetailFileUpload.TryBuildViewUrl(relativePath, userName, out url, out errorMessage))
            {
                MsgBox.ShowWarning(errorMessage);
                return;
            }

            OpenNewTab(url);
        }
    }
}

