        private string RenameLinkAfterInsert(long employeeId, long taskId, string fileName)
        {
            if (taskId <= 0 || string.IsNullOrEmpty(fileName))
                return fileName;

            string prefix = string.Format(CultureInfo.InvariantCulture, "0_{0}_", employeeId);
            if (!fileName.StartsWith(prefix))
                return fileName;

            string tail = fileName.Substring(prefix.Length);
            string newName = taskId.ToString(CultureInfo.InvariantCulture) + "_" + tail;
            EnsureFilePath();
            string oldPath = FilePath + fileName;
            string newPath = FilePath + newName;
            if (File.Exists(oldPath))
            {
                if (File.Exists(newPath))
                    File.Delete(newPath);
                File.Move(oldPath, newPath);
            }
            return newName;
        }

