            upCongTac.Update();
        }

        protected void ucEdit_DataSaved(object sender, EventArgs e)
        {
            LoadGrid();
            upCongTac.Update();
        }

        protected void gvCongTac_RowDataBound(object sender, GridViewRowEventArgs e)
        {
            if (e.Row.RowType != DataControlRowType.DataRow)
                return;

            bool canEdit = EmployeeV2TabCanEdit.CanEdit(Session);
            LinkButton btnEdit = e.Row.FindControl("btnEdit") as LinkButton;
            if (btnEdit != null && !canEdit)
                btnEdit.Visible = false;

            LinkButton btnDelete = e.Row.FindControl("btnDelete") as LinkButton;
            if (btnDelete != null && !canEdit)
                btnDelete.Visible = false;
        }

        protected void gvCongTac_RowCommand(object sender, GridViewCommandEventArgs e)
        {
            int index;
            if (!int.TryParse(Convert.ToString(e.CommandArgument), out index))
                return;

            if (index < 0 || index >= gvCongTac.Rows.Count)
                return;

            if (e.CommandName == "EditRow")
            {
                if (!EmployeeV2TabCanEdit.CanEdit(Session))
                    return;

                long taskId = GetTaskIdFromRow(index);
                if (taskId > 0)
                    ucEdit.OpenForEdit(taskId);
            }
            else if (e.CommandName == "DeleteRow")
            {
                if (!EmployeeV2TabCanEdit.CanEdit(Session))
                {
                    MsgBox.ShowWarning("Bạn không được phép xóa hoặc đã hết hạn chỉnh sửa.");
                    return;
                }

                DeleteRow(index);
                LoadGrid();
                upCongTac.Update();
            }
        }

        protected string GetLink(object contentFile)
        {
            if (contentFile != null && contentFile.ToString() != string.Empty)
            {
                return string.Format(CultureInfo.InvariantCulture,
                    "<a style='color:blue' target='_blank' href='{0}{1}'>Tải tập tin</a>",
                    strFilePath_Logis,
                    contentFile);
            }
            return string.Empty;
        }

        protected object GetRowValue(object dataItem, string fieldName)
        {
            DataRowView row = dataItem as DataRowView;
            if (row == null || row.Row == null || row.Row.Table == null)
                return null;
            if (!row.Row.Table.Columns.Contains(fieldName))
                return null;
            return row[fieldName];
        }

        protected string GetText(object dataItem, string fieldName)
        {
            object value = GetRowValue(dataItem, fieldName);
            if (value == null || value == DBNull.Value)
                return string.Empty;
            return value.ToString().Trim();
        }

        protected string FormatDateField(object dataItem, string fieldName)
        {
            object value = GetRowValue(dataItem, fieldName);
            if (value == null || value == DBNull.Value)
                return string.Empty;

            DateTime d;
            if (value is DateTime)
                d = (DateTime)value;
            else if (!DateTime.TryParse(value.ToString(), CultureInfo.CurrentCulture, DateTimeStyles.None, out d))
                return string.Empty;

            return d.ToString("dd/MM/yyyy");
        }

        private void RefreshFileLogisPrefix()
        {
            long employeeId = GetEmployeeId();
            strFilePath_Logis = Globals.GetConfig("LogicalDirectory_Upload") + "/Data/HRS_Task/"
                + employeeId.ToString(CultureInfo.InvariantCulture) + "/";
        }

        private void LoadGrid()
        {
            long employeeId = GetEmployeeId();
            DataTable dt = null;
            if (employeeId > 0)
            {
                try
                {
                    dt = employeeDao.GetDataTable(StoreSearch, "@EmployeeID", employeeId);
                }
                catch (Exception ex)
                {
                    System.Diagnostics.Debug.WriteLine("TabCongTac.LoadGrid: " + ex.Message);
                }
            }

            if (dt == null)
                dt = new DataTable();

            gvCongTac.DataSource = dt;
            gvCongTac.DataBind();
        }

        private long GetTaskIdFromRow(int rowIndex)
        {
            if (gvCongTac.DataKeys == null || rowIndex >= gvCongTac.DataKeys.Count)
                return 0;

            object key = gvCongTac.DataKeys[rowIndex].Value;
            if (key == null || key == DBNull.Value)
                return 0;

            long taskId;
            long.TryParse(key.ToString(), out taskId);
            return taskId;
        }

        private void DeleteRow(int rowIndex)
        {
            long taskId = GetTaskIdFromRow(rowIndex);
            if (taskId <= 0)
                return;

            SessionUser objUser = Session[Globals.USER] as SessionUser;
            string userName = objUser != null ? objUser.UserName.ToLower() : string.Empty;

            HRS_Task item = new HRS_Task();
            item.TaskID = taskId;
            string linkToDelete = string.Empty;
            if (item.Get())
                linkToDelete = SafeText(item.Link);

            item.DeletedUser = userName;
            item.BeginTransaction();
            try
            {
                if (!item.Delete())
                {
                    MsgBox.ShowWarning("Không thể xóa quá trình công tác.");
                    return;
                }
                item.CommitTransaction();

                if (!string.IsNullOrEmpty(linkToDelete))
                {
                    long employeeId = GetEmployeeId();
                    string physicalDir = Globals.GetConfig("PhysicalDirectory_Upload") + "\\Data\\HRS_Task\\"
                        + employeeId.ToString(CultureInfo.InvariantCulture) + "\\";
                    string physicalFile = physicalDir + linkToDelete;
                    if (File.Exists(physicalFile))
                        File.Delete(physicalFile);
                }
            }
            catch (Exception ex)
            {
                System.Diagnostics.Debug.WriteLine("TabCongTac.Delete: " + ex.Message);
                MsgBox.ShowError("Lỗi khi xóa quá trình công tác.");
            }
        }

        private void ApplyEditPermission()
        {
            bool canEdit = EmployeeV2TabCanEdit.CanEdit(Session);
            if (pnlAddToolbar != null)
                pnlAddToolbar.Visible = canEdit;
            if (btnAdd != null)
                btnAdd.Visible = canEdit;
            if (btnRefresh != null)
                btnRefresh.Visible = canEdit;
        }

        private long GetEmployeeId()
        {
            object o = ViewState["EmpV2_CongTac_EmployeeID"];
            if (o != null)
            {
                long id;
                if (long.TryParse(o.ToString(), out id) && id > 0)
                    return id;
            }

            if (hidEmployeeID != null && !string.IsNullOrWhiteSpace(hidEmployeeID.Value))
            {
                long id;
                if (long.TryParse(hidEmployeeID.Value, out id) && id > 0)
                    return id;
            }

            return 0;
        }

        private static string SafeText(object value)
        {
            if (value == null || value == DBNull.Value)
                return string.Empty;
            return value.ToString().Trim();
        }
    }
}

