protected void fileUpload_UploadedComplete(object sender, AsyncFileUploadEventArgs e)
{
    ClearTaskLinkSession();
    if (fileUpload == null || !fileUpload.HasFile)
        return;

    string strFileName = fileUpload.FileName.Replace(" ", "-");
    if (strFileName.Length < 2)
        return;

    if (IsBlockedUploadExtension(strFileName))
        return;

    long employeeId = GetEmployeeId();
    if (employeeId <= 0)
        return;

    EnsureFilePath();
    try
    {
        Directory.CreateDirectory(FilePath);
    }
    catch (Exception ex)
    {
        System.Diagnostics.Debug.WriteLine("TabCongTacEdit.Upload: " + ex.Message);
        return;
    }

    long taskId = 0;
    long.TryParse(hdnTaskID.Value, out taskId);
    string mmdd = DateTime.Now.ToString("MMdd", CultureInfo.InvariantCulture);
    if (taskId > 0)
        strFileName = taskId.ToString(CultureInfo.InvariantCulture) + "_" + mmdd + "_" + strFileName;
    else
        strFileName = "0_" + employeeId.ToString(CultureInfo.InvariantCulture) + "_" + mmdd + "_" + strFileName;

    try
    {
        fileUpload.SaveAs(FilePath + strFileName);
    }
    catch (Exception ex)
    {
        System.Diagnostics.Debug.WriteLine("TabCongTacEdit.SaveAs: " + ex.Message);
        return;
    }

    SetContentFileName(strFileName);
    Session["fileUpload" + ClientID] = strFileName;
}

